-- Net ERC-20 flow into each hack-linked frozen address, from the window start
-- (block 26300743) up to the log just before its freeze event. This is a window-only
-- balance: it is the frozen amount only if the address held none of that token before
-- block 26300743. A full-history sum from each token's deployment timed out on staging
-- (10-minute query deadline), so the absolute balance waits on a derived dataset.
-- USDT also moves balances without Transfer logs (issue, redeem, destroyBlackFunds).
-- Generated by scripts/freeze/build.mjs from freeze-events.sql and the trace.
WITH frozen AS (
  SELECT * FROM (VALUES
    (evm_encode_hex('0x0000000000000000000000005227f603c1ee34ce3c06efe6477003bdfccb2f8c'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26300954, 302),
    (evm_encode_hex('0x0000000000000000000000009749292d74fd460982d0912ea9515ea24736c762'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26300954, 305),
    (evm_encode_hex('0x0000000000000000000000000ddf0480016e6bcb2c1f5d190d221fba1320697e'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26300955, 257),
    (evm_encode_hex('0x0000000000000000000000008d53903625b8e839b9df4bd28b0efb1cd6b8639a'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26300960, 474),
    (evm_encode_hex('0x0000000000000000000000005227f603c1ee34ce3c06efe6477003bdfccb2f8c'), evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48'), 26300971, 316),
    (evm_encode_hex('0x0000000000000000000000005227f603c1ee34ce3c06efe6477003bdfccb2f8c'), evm_encode_hex('0x68749665ff8d2d112fa859aa293f07a622782f38'), 26301003, 353),
    (evm_encode_hex('0x0000000000000000000000007aa4d3029e4c6a8e916300014ad95b6d6c03bfd1'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26301009, 284),
    (evm_encode_hex('0x000000000000000000000000aa246bf639586a6ba46762d378ce50ca4fc654a0'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26301021, 562),
    (evm_encode_hex('0x000000000000000000000000ccbef95633adb5cd2b5038db5a38d77e726ca263'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26301030, 323),
    (evm_encode_hex('0x000000000000000000000000b171ca86f82070282138352ff7111b494060c8c3'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26301041, 129),
    (evm_encode_hex('0x000000000000000000000000e7024ab80143b1ef843efe6a58368696cb87958d'), evm_encode_hex('0x8292bb45bf1ee4d140127049757c2e0ff06317ed'), 26301251, 1392),
    (evm_encode_hex('0x00000000000000000000000028c6c06298d514db089934071355e5743bf21d60'), evm_encode_hex('0xdac17f958d2ee523a2206206994597c13d831ec7'), 26301278, 44),
    (evm_encode_hex('0x0000000000000000000000005227f603c1ee34ce3c06efe6477003bdfccb2f8c'), evm_encode_hex('0x8d0d000ee44948fc98c9b98a4fa4921476f08b0d'), 26301299, 141),
    (evm_encode_hex('0x00000000000000000000000028c6c06298d514db089934071355e5743bf21d60'), evm_encode_hex('0x8292bb45bf1ee4d140127049757c2e0ff06317ed'), 26301350, 705),
    (evm_encode_hex('0x00000000000000000000000028c6c06298d514db089934071355e5743bf21d60'), evm_encode_hex('0x8d0d000ee44948fc98c9b98a4fa4921476f08b0d'), 26301377, 588),
    (evm_encode_hex('0x0000000000000000000000005227f603c1ee34ce3c06efe6477003bdfccb2f8c'), evm_encode_hex('0x6c3ea9036406852006290770bedfcaba0e23a0e8'), 26301400, 48),
    (evm_encode_hex('0x0000000000000000000000005227f603c1ee34ce3c06efe6477003bdfccb2f8c'), evm_encode_hex('0x45804880de22913dafe09f4980848ece6ecbaf78'), 26301400, 51),
    (evm_encode_hex('0x00000000000000000000000028c6c06298d514db089934071355e5743bf21d60'), evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48'), 26301812, 119),
    (evm_encode_hex('0x000000000000000000000000ee7ae85f2fe2239e27d9c1e23fffe168d63b4055'), evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48'), 26301819, 296),
    (evm_encode_hex('0x000000000000000000000000a97bf7836f8a08f9ed91d41453d371493fae8d10'), evm_encode_hex('0x6c3ea9036406852006290770bedfcaba0e23a0e8'), 26301890, 59),
    (evm_encode_hex('0x000000000000000000000000a97bf7836f8a08f9ed91d41453d371493fae8d10'), evm_encode_hex('0x45804880de22913dafe09f4980848ece6ecbaf78'), 26301890, 148),
    (evm_encode_hex('0x0000000000000000000000005227f603c1ee34ce3c06efe6477003bdfccb2f8c'), evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409'), 26302072, 29),
    (evm_encode_hex('0x00000000000000000000000028c6c06298d514db089934071355e5743bf21d60'), evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409'), 26302072, 30),
    (evm_encode_hex('0x000000000000000000000000cf4ca2bdf21bc3a467a00b6afe72b833982723e0'), evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409'), 26302072, 31),
    (evm_encode_hex('0x000000000000000000000000e7024ab80143b1ef843efe6a58368696cb87958d'), evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409'), 26302072, 32),
    (evm_encode_hex('0x000000000000000000000000b3ddec0ccc5c3ba733fcdf5a15f98c95ec5a5fdb'), evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409'), 26302072, 33),
    (evm_encode_hex('0x00000000000000000000000042cdf00c85005630cc8605731b9364f712077810'), evm_encode_hex('0xc5f0f7b66764f6ec8c8dff7ba683102295e16409'), 26302072, 34),
    (evm_encode_hex('0x000000000000000000000000b3ddec0ccc5c3ba733fcdf5a15f98c95ec5a5fdb'), evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48'), 26302175, 649),
    (evm_encode_hex('0x000000000000000000000000a97bf7836f8a08f9ed91d41453d371493fae8d10'), evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48'), 26303095, 356),
    (evm_encode_hex('0x0000000000000000000000008c1c499b1796d7f3c2521ac37186b52de024e58c'), evm_encode_hex('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48'), 26303134, 61)
  ) AS f(account_topic, token, freeze_block, freeze_log)
),
t AS (
  SELECT block_num, log_index, address AS token, topic1, topic2,
         arrow_cast(evm_decode_log(topic1, topic2, topic3, data, 'Transfer(address indexed from, address indexed to, uint256 value)')['value'], 'Decimal128(38,0)') AS v
  FROM "{{dataset}}".logs
  WHERE _block_num BETWEEN 26300743 AND 26303134
    AND topic0 = evm_topic('Transfer(address indexed from, address indexed to, uint256 value)')
    AND topic3 IS NULL
    AND address IN (SELECT DISTINCT token FROM frozen)
    AND (topic1 IN (SELECT account_topic FROM frozen) OR topic2 IN (SELECT account_topic FROM frozen))
)
SELECT
  '0x' || substr(evm_decode_hex(f.account_topic), 27) AS account,
  evm_decode_hex(f.token) AS token_address,
  f.freeze_block,
  count(t.v) AS transfers,
  arrow_cast(coalesce(sum(CASE WHEN t.topic2 = f.account_topic THEN t.v END), 0)
           - coalesce(sum(CASE WHEN t.topic1 = f.account_topic THEN t.v END), 0), 'Utf8') AS net_raw
FROM frozen AS f
LEFT JOIN t
  ON t.token = f.token
 AND (t.topic1 = f.account_topic OR t.topic2 = f.account_topic)
 AND (t.block_num < f.freeze_block OR (t.block_num = f.freeze_block AND t.log_index < f.freeze_log))
GROUP BY 1, 2, 3
ORDER BY 3
